<?php
declare(strict_types=1);
$uriPath = parse_url($_SERVER['REQUEST_URI'] ?? '/', PHP_URL_PATH) ?: '/';
if (str_starts_with($uriPath, '/api/v1/')) { require __DIR__ . '/api/v1/index.php'; exit; }
if (str_starts_with($uriPath, '/widget/')) { require __DIR__ . '/widget/diet-order.php'; exit; }
if (PHP_SAPI === 'cli-server') { $static = __DIR__ . $uriPath; if (is_file($static) && pathinfo($static, PATHINFO_EXTENSION) !== 'php') return false; }
require_once __DIR__ . '/../src/bootstrap.php';
require_once __DIR__ . '/../templates/layout.php';

$page = $_GET['page'] ?? 'dashboard';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf($_POST['csrf_token'] ?? null);
    $action = $_POST['action'] ?? '';
    if ($action === 'update_tray') {
        $repo->update('trays', (int)$_POST['id'], ['status'=>trim($_POST['status']), 'updated_at'=>now_iso()]);
        $_SESSION['flash'] = 'Tray status updated successfully.';
        redirect('/?page=trays');
    }
    if ($action === 'record_wastage') {
        $ingredient = $repo->find('ingredients', (int)$_POST['ingredient_id']);
        if ($ingredient) {
            $qty = max(0, (float)$_POST['quantity']);
            $repo->update('ingredients', (int)$ingredient['id'], ['on_hand'=>max(0, (float)$ingredient['on_hand']-$qty)]);
            $repo->insert('wastage', ['ingredient'=>$ingredient['name'],'quantity'=>$qty,'unit'=>$ingredient['unit'],'reason'=>trim($_POST['reason']),'recorded_at'=>now_iso(),'recorded_by'=>'Kitchen Supervisor']);
        }
        $_SESSION['flash'] = 'Wastage recorded and stock adjusted.';
        redirect('/?page=wastage');
    }
    if ($action === 'create_order') {
        $patient = $repo->find('patients', (int)$_POST['patient_id']);
        $diet = $repo->find('diet_types', (int)$_POST['diet_type_id']);
        $clinician = $repo->find('clinicians', (int)$_POST['clinician_id']);
        if ($patient && $diet && $clinician) {
            $repo->insert('diet_orders', ['patient_id'=>$patient['id'],'patient_name'=>$patient['name'],'diet_code'=>$diet['code'],'diet_name'=>$diet['name'],'clinician_name'=>$clinician['name'],'effective_from'=>$_POST['effective_from'],'meal_texture'=>trim($_POST['meal_texture']),'calories'=>(int)$_POST['calories'],'notes'=>trim($_POST['notes']),'status'=>'active']);
            $_SESSION['flash'] = 'Diet order created and queued for kitchen review.';
        }
        redirect('/?page=diet-orders');
    }
    if ($action === 'create_menu') {
        $items = array_values(array_filter(array_map('trim', preg_split('/[\\r\\n|]+/', (string)($_POST['items'] ?? '')))));
        $repo->insert('menus', ['menu_date'=>$_POST['menu_date'],'meal_period'=>trim($_POST['meal_period']),'title'=>trim($_POST['title']),'status'=>trim($_POST['status'] ?? 'Planning'),'items'=>implode('|',$items),'calories'=>(int)($_POST['calories'] ?? 0),'protein_g'=>(float)($_POST['protein_g'] ?? 0),'carbs_g'=>(float)($_POST['carbs_g'] ?? 0),'fat_g'=>(float)($_POST['fat_g'] ?? 0)]);
        $_SESSION['flash'] = 'Menu created successfully.';
        redirect('/?page=menus');
    }
    if ($action === 'update_menu') {
        $items = array_values(array_filter(array_map('trim', preg_split('/[\\r\\n|]+/', (string)($_POST['items'] ?? '')))));
        $repo->update('menus', (int)$_POST['id'], ['menu_date'=>$_POST['menu_date'],'meal_period'=>trim($_POST['meal_period']),'title'=>trim($_POST['title']),'status'=>trim($_POST['status']),'items'=>implode('|',$items),'calories'=>(int)($_POST['calories'] ?? 0),'protein_g'=>(float)($_POST['protein_g'] ?? 0),'carbs_g'=>(float)($_POST['carbs_g'] ?? 0),'fat_g'=>(float)($_POST['fat_g'] ?? 0)]);
        $_SESSION['flash'] = 'Menu updated successfully.';
        redirect('/?page=menus');
    }
    if ($action === 'scan_tray') {
        $tray = current(array_filter($repo->all('trays'), fn($t)=>(string)($t['tray_ref'] ?? '') === trim((string)$_POST['tray_ref']))) ?: null;
        if ($tray) {
            $repo->update('trays', (int)$tray['id'], ['status'=>trim($_POST['status']),'updated_at'=>now_iso()]);
            $_SESSION['flash'] = 'Tray '.$tray['tray_ref'].' updated successfully.';
        } else $_SESSION['flash'] = 'Tray reference not found. Check the code and try again.';
        redirect('/?page=trays');
    }
    if ($action === 'record_intake') {
        $tray = $repo->find('trays', (int)$_POST['tray_id']);
        if ($tray) {
            $percent = max(0, min(100, (int)$_POST['consumed_percent']));
            $status = trim($_POST['status']);
            $repo->update('trays', (int)$tray['id'], ['status'=>$status,'updated_at'=>now_iso()]);
            $repo->insert('consumption', ['tray_ref'=>$tray['tray_ref'],'patient_name'=>$tray['patient_name'],'status'=>$status,'consumed_percent'=>$percent,'refusal_reason'=>trim($_POST['refusal_reason'] ?? ''),'recorded_at'=>now_iso(),'recorded_by'=>'Kitchen Supervisor']);
            $_SESSION['flash'] = 'Consumption outcome recorded.';
        }
        redirect('/?page=trays');
    }
    if ($action === 'record_receipt') {
        $ingredient = $repo->find('ingredients', (int)$_POST['ingredient_id']);
        $qty = max(0, (float)$_POST['quantity']);
        if ($ingredient && $qty > 0) {
            $repo->update('ingredients', (int)$ingredient['id'], ['on_hand'=>(float)$ingredient['on_hand'] + $qty]);
            $repo->insert('stock_movements', ['ingredient_id'=>$ingredient['id'],'movement_type'=>'receipt','quantity'=>$qty,'reference_text'=>trim($_POST['reference'] ?? ''),'performed_by'=>'Storekeeper','performed_at'=>now_iso()]);
            $_SESSION['flash'] = 'Stock receipt recorded.';
        }
        redirect('/?page=inventory');
    }
    if ($action === 'update_ingredient') {
        $ingredient = $repo->find('ingredients', (int)$_POST['id']);
        if ($ingredient) {
            $repo->update('ingredients', (int)$ingredient['id'], ['on_hand'=>max(0, (float)$_POST['on_hand']),'reorder_level'=>max(0, (float)$_POST['reorder_level']),'expiry_date'=>$_POST['expiry_date']]);
            $_SESSION['flash'] = 'Inventory item updated.';
        }
        redirect('/?page=inventory');
    }
}

switch ($page) {
    case 'diet-orders': render_orders($repo); break;
    case 'menus': render_menus($repo); break;
    case 'trays': render_trays($repo); break;
    case 'inventory': render_inventory($repo); break;
    case 'wastage': render_wastage($repo); break;
    default: render_dashboard($repo);
}

function render_dashboard(Repository $repo): void {
    layout_start('Dashboard','dashboard'); $stats=$repo->dashboard(); $orders=$repo->all('diet_orders'); $trays=$repo->all('trays'); $ingredients=$repo->all('ingredients'); ?>
    <section class="welcome-row"><div><h2>Good morning, Kitchen Supervisor</h2><p>Here is the service overview for <?= e(date('l, d M Y')) ?>.</p></div><a class="btn btn-primary" href="/?page=diet-orders#new-order"><i class="bi bi-plus-lg me-2"></i>New diet order</a></section>
    <div class="stats-grid"><?php stat_card('Active diet orders',(string)$stats['active_orders'],'clipboard2-pulse','purple','Across all wards'); stat_card("Today's trays",(string)$stats['trays_today'],'box-seam','blue',$stats['delivered'].' delivered'); stat_card('Low stock items',(string)$stats['low_stock'],'exclamation-triangle','orange','Needs attention'); stat_card('Wastage logged',number_format($stats['wastage_total'],1).' kg','recycle','green','This service period'); ?></div>
    <div class="content-grid mt-4"><div class="panel"><div class="panel-heading"><div><h3>Meal service status</h3><p>Today’s tray progress by service state.</p></div><a href="/?page=trays" class="text-link">View all <i class="bi bi-arrow-up-right"></i></a></div><div class="progress-stack"><div class="progress-row"><span>Delivered</span><strong><?= $stats['delivered'] ?></strong><div class="progress"><div class="progress-bar bg-success" style="width:<?= max(8, $stats['trays_today']?($stats['delivered']/$stats['trays_today']*100):0) ?>%"></div></div></div><div class="progress-row"><span>In preparation</span><strong><?= count(array_filter($trays,fn($t)=>in_array($t['status'],['Assembled','Dispatched']))) ?></strong><div class="progress"><div class="progress-bar bg-primary" style="width:45%"></div></div></div><div class="progress-row"><span>Planned</span><strong><?= count(array_filter($trays,fn($t)=>$t['status']==='Planned')) ?></strong><div class="progress"><div class="progress-bar bg-secondary" style="width:25%"></div></div></div></div></div>
    <div class="panel alert-panel"><div class="panel-heading"><div><h3>Attention needed</h3><p>Items that may affect today’s service.</p></div><i class="bi bi-shield-check text-success fs-4"></i></div><div class="attention-item"><div class="attention-icon danger"><i class="bi bi-boxes"></i></div><div><strong><?= $stats['low_stock'] ?> ingredients below reorder level</strong><span>Review inventory and raise a purchase request.</span></div><a href="/?page=inventory" class="icon-link"><i class="bi bi-chevron-right"></i></a></div><div class="attention-item"><div class="attention-icon warning"><i class="bi bi-clock-history"></i></div><div><strong><?= count(array_filter($orders,fn($o)=>$o['status']==='draft')) ?> diet orders awaiting review</strong><span>Confirm prescribed diets before the next meal cycle.</span></div><a href="/?page=diet-orders" class="icon-link"><i class="bi bi-chevron-right"></i></a></div></div></div>
    <div class="panel mt-4"><div class="panel-heading"><div><h3>Recent diet orders</h3><p>Latest patient-linked meal instructions.</p></div><a href="/?page=diet-orders" class="text-link">Manage orders <i class="bi bi-arrow-up-right"></i></a></div><div class="table-responsive"><table class="table app-table"><thead><tr><th>Patient</th><th>Diet</th><th>Prescriber</th><th>Effective</th><th>Status</th></tr></thead><tbody><?php foreach(array_slice($orders,0,5) as $o): ?><tr><td><strong><?= e($o['patient_name']) ?></strong><small class="d-block text-muted"><?= e($o['notes']) ?></small></td><td><span class="diet-tag"><?= e($o['diet_code']) ?></span> <?= e($o['diet_name']) ?></td><td><?= e($o['clinician_name']) ?></td><td><?= e(date('d M Y',strtotime($o['effective_from']))) ?></td><td><?= status_badge($o['status']) ?></td></tr><?php endforeach; ?></tbody></table></div></div>
    <?php layout_end();
}

