= e($values['carbs_g']) ?>"></div><div class="col-6"><label class="form-label">Fat (g)</label><input class="form-control" type="number" min="0" step="0.1" name="fat_g" value="<?= e($values['fat_g']) ?>"></div></div></div></div><button class="btn btn-primary mt-3"><i class="bi bi-check2 me-2"></i><?= $editing ? 'Save menu changes' : 'Create menu' ?></button></form></div>
    <?php endif; ?>
    <div class="calendar-strip"><div class="calendar-day active"><small>Today</small><strong><?= date('d') ?></strong><span><?= date('M') ?></span></div><div class="calendar-day"><small>Tomorrow</small><strong><?= date('d',strtotime('+1 day')) ?></strong><span><?= date('M',strtotime('+1 day')) ?></span></div><div class="calendar-day"><small><?= date('D',strtotime('+2 day')) ?></small><strong><?= date('d',strtotime('+2 day')) ?></strong><span><?= date('M',strtotime('+2 day')) ?></span></div><div class="calendar-day"><small><?= date('D',strtotime('+3 day')) ?></small><strong><?= date('d',strtotime('+3 day')) ?></strong><span><?= date('M',strtotime('+3 day')) ?></span></div><div class="calendar-day"><small><?= date('D',strtotime('+4 day')) ?></small><strong><?= date('d',strtotime('+4 day')) ?></strong><span><?= date('M',strtotime('+4 day')) ?></span></div></div>
