    <?php if ($showScan): ?><div class="panel mb-4" id="tray-scan"><div class="panel-heading"><div><h3>Scan or update tray</h3><p>Enter the tray reference from the label and select the confirmed status.</p></div><a class="btn btn-light" href="/?page=trays">Cancel</a></div><form method="post" class="row g-3 align-items-end"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="scan_tray"><div class="col-md-5"><label class="form-label">Tray reference</label><input class="form-control" name="tray_ref" placeholder="e.g. TRAY-24001" required autofocus></div><div class="col-md-4"><label class="form-label">New status</label><select class="form-select" name="status"><?php foreach(['Planned','Assembled','Dispatched','Delivered','Consumed','Refused','Returned','Not Received'] as $status): ?><option><?= $status ?></option><?php endforeach; ?></select></div><div class="col-md-3"><button class="btn btn-primary w-100">Update tray</button></div></form></div><?php endif; ?>
    <?php if ($showIntake): ?><div class="panel mb-4" id="intake-form"><div class="panel-heading"><div><h3>Record meal intake</h3><p>Record consumption, refusal, or a missed handover against the tray.</p></div><a class="btn btn-light" href="/?page=trays">Cancel</a></div><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="record_intake"><div class="row g-3"><div class="col-md-4"><label class="form-label">Tray</label><select class="form-select" name="tray_id" required><?php foreach($trays as $t): ?><option value="<?= (int)$t['id'] ?>" <?= $intakeTray && (int)$intakeTray['id']===(int)$t['id']?'selected':'' ?>><?= e($t['tray_ref'].' · '.$t['patient_name'].' · '.$t['meal_period']) ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Outcome</label><select class="form-select" name="status"><option>Consumed</option><option>Partially Consumed</option><option>Refused</option><option>Not Received</option></select></div><div class="col-md-2"><label class="form-label">Consumed %</label><input class="form-control" type="number" name="consumed_percent" min="0" max="100" value="100"></div><div class="col-md-3"><label class="form-label">Refusal / exception note</label><input class="form-control" name="refusal_reason" placeholder="Optional reason"></div></div><button class="btn btn-primary mt-3">Save intake outcome</button></form></div><?php endif; ?>
    <div class="kanban-grid"><?php foreach(['Planned','Assembled','Dispatched','Delivered'] as $stage): ?><div class="kanban-column"><div class="kanban-heading"><strong><?= e($stage) ?></strong><span><?= count(array_filter($trays,fn($t)=>$t['status']===$stage)) ?></span></div><?php foreach(array_filter($trays,fn($t)=>$t['status']===$stage) as $t): ?><div class="tray-card"><div class="d-flex justify-content-between align-items-start"><strong><?= e($t['tray_ref']) ?></strong><?= status_badge($t['status']) ?></div><h4><?= e($t['patient_name']) ?></h4><div class="tray-meta"><span><i class="bi bi-geo-alt"></i><?= e($t['ward']) ?></span><span><i class="bi bi-clock"></i><?= e($t['meal_period']) ?></span></div><div class="tray-diet"><span class="diet-tag"><?= e($t['diet']) ?></span> diet protocol</div><form method="post" class="mt-3 d-flex gap-2"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="update_tray"><input type="hidden" name="id" value="<?= (int)$t['id'] ?>"><select name="status" class="form-select form-select-sm"><?php foreach(['Planned','Assembled','Dispatched','Delivered','Consumed','Refused','Returned','Not Received'] as $status): ?><option <?= $t['status']===$status?'selected':'' ?>><?= $status ?></option><?php endforeach; ?></select><button class="btn btn-sm btn-light" title="Update status"><i class="bi bi-arrow-right"></i></button></form></div><?php endforeach; ?></div><?php endforeach; ?></div>
    <div class="panel mt-4"><div class="panel-heading"><div><h3>Consumption recording</h3><p>Recent patient intake feedback.</p></div><a class="text-link" href="/api/v1/export/daily-kitchen.csv" target="_blank">Export daily log <i class="bi bi-download"></i></a></div><div class="table-responsive"><table class="table app-table"><thead><tr><th>Tray</th><th>Patient</th><th>Consumption</th><th>Recorded</th><th>Action</th></tr></thead><tbody><?php foreach($repo->all('consumption') as $c): $matched = current(array_filter($trays,fn($t)=>(string)($t['tray_ref']??'')===(string)($c['tray_ref']??''))) ?: null; ?><tr><td><strong><?= e($c['tray_ref']) ?></strong></td><td><?= e($c['patient_name']) ?></td><td><div class="consumption-bar"><div style="width:<?= (int)$c['consumed_percent'] ?>%"></div></div><span class="small"><?= e($c['consumed_percent']) ?>% · <?= e($c['status']) ?></span></td><td><?= e($c['recorded_at']) ?></td><td><?= $matched ? '<a class="btn btn-sm btn-outline-secondary" href="/?page=trays&intake_id='.(int)$matched['id'].'#intake-form">Record intake</a>' : '<span class="text-muted">—</span>' ?></td></tr><?php endforeach; ?></tbody></table></div></div>
    <?php layout_end();
}

function render_inventory(Repository $repo): void {
    layout_start('Inventory','inventory');
    $items = $repo->all('ingredients');
    $editing = ($_GET['edit_id'] ?? '') !== '' ? $repo->find('ingredients', (int)$_GET['edit_id']) : null;
    $showReceipt = ($_GET['form'] ?? '') === 'receipt';
    $showEdit = (bool)$editing;
    $lowOnly = ($_GET['low'] ?? '') === '1';
    $visibleItems = $lowOnly ? array_values(array_filter($items,fn($i)=>(float)$i['on_hand']<=(float)$i['reorder_level'])) : $items;
    ?>
    <section class="page-intro"><div><span class="eyebrow">STORES & STOCK</span><h2>Kitchen inventory</h2><p>Monitor ingredients, reorder thresholds, expiry risk, and stock movements.</p></div><a class="btn btn-primary" href="/?page=inventory&form=receipt#inventory-form"><i class="bi bi-box-arrow-in-down me-2"></i>Record receipt</a></section>
    <?php if ($showReceipt || $showEdit): ?><div class="panel mb-4" id="inventory-form"><div class="panel-heading"><div><h3><?= $showEdit ? 'Edit inventory item' : 'Record stock receipt' ?></h3><p><?= $showEdit ? 'Update the on-hand balance, reorder level, and expiry date.' : 'Add received stock to an ingredient and preserve the receipt reference.' ?></p></div><a class="btn btn-light" href="/?page=inventory">Cancel</a></div><?php if($showEdit): ?><form method="post" class="row g-3 align-items-end"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="update_ingredient"><input type="hidden" name="id" value="<?= (int)$editing['id'] ?>"><div class="col-md-4"><label class="form-label">Ingredient</label><input class="form-control" value="<?= e($editing['name'].' · '.$editing['sku']) ?>" disabled></div><div class="col-md-2"><label class="form-label">On hand</label><input class="form-control" type="number" step="0.1" min="0" name="on_hand" value="<?= e($editing['on_hand']) ?>"></div><div class="col-md-2"><label class="form-label">Reorder level</label><input class="form-control" type="number" step="0.1" min="0" name="reorder_level" value="<?= e($editing['reorder_level']) ?>"></div><div class="col-md-2"><label class="form-label">Expiry</label><input class="form-control" type="date" name="expiry_date" value="<?= e($editing['expiry_date']) ?>"></div><div class="col-md-2"><button class="btn btn-primary w-100">Save changes</button></div></form><?php else: ?><form method="post" class="row g-3 align-items-end"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="record_receipt"><div class="col-md-5"><label class="form-label">Ingredient</label><select class="form-select" name="ingredient_id" required><?php foreach($items as $i): ?><option value="<?= (int)$i['id'] ?>"><?= e($i['name'].' · '.$i['on_hand'].' '.$i['unit'].' on hand') ?></option><?php endforeach; ?></select></div><div class="col-md-2"><label class="form-label">Quantity</label><input class="form-control" type="number" step="0.1" min="0.1" name="quantity" required></div><div class="col-md-3"><label class="form-label">Receipt reference</label><input class="form-control" name="reference" placeholder="GRN / invoice no."></div><div class="col-md-2"><button class="btn btn-primary w-100">Save receipt</button></div></form><?php endif; ?></div><?php endif; ?>
    <div class="stats-grid compact"><div class="stat-card"><div class="stat-icon blue"><i class="bi bi-boxes"></i></div><div><div class="stat-label">Tracked ingredients</div><div class="stat-value"><?= count($items) ?></div></div></div><div class="stat-card"><div class="stat-icon orange"><i class="bi bi-exclamation-triangle"></i></div><div><div class="stat-label">Below reorder level</div><div class="stat-value"><?= count(array_filter($items,fn($i)=>(float)$i['on_hand']<=(float)$i['reorder_level'])) ?></div></div></div><div class="stat-card"><div class="stat-icon purple"><i class="bi bi-calendar-x"></i></div><div><div class="stat-label">Expiry within 7 days</div><div class="stat-value"><?= count(array_filter($items,fn($i)=>!empty($i['expiry_date']) && strtotime($i['expiry_date'])<=strtotime('+7 days'))) ?></div></div></div></div><div class="panel mt-4" id="inventory-table"><div class="filter-bar inside"><div class="search-box"><i class="bi bi-search"></i><input id="tableSearch" type="search" placeholder="Search ingredients"></div><a class="btn btn-light" href="/?page=inventory&low=<?= $lowOnly?'0':'1' ?>#inventory-table"><i class="bi bi-funnel me-2"></i><?= $lowOnly?'Show all':'Low-stock only' ?></a></div><div class="table-responsive"><table class="table app-table searchable-table"><thead><tr><th>Ingredient</th><th>Category</th><th>On hand</th><th>Reorder level</th><th>Expiry</th><th>Stock health</th><th></th></tr></thead><tbody><?php foreach($visibleItems as $i): $low=(float)$i['on_hand']<=(float)$i['reorder_level']; $soon=!empty($i['expiry_date']) && strtotime($i['expiry_date'])<=strtotime('+7 days'); ?><tr><td><strong><?= e($i['name']) ?></strong><small class="d-block text-muted"><?= e($i['sku']) ?></small></td><td><?= e($i['category']) ?></td><td><strong><?= e($i['on_hand']) ?></strong> <?= e($i['unit']) ?></td><td><?= e($i['reorder_level']) ?> <?= e($i['unit']) ?></td><td class="<?= $soon?'text-danger fw-semibold':'' ?>"><?= e(date('d M Y',strtotime($i['expiry_date']))) ?><?= $soon?' <small>(soon)</small>':'' ?></td><td><?= $low?status_badge('Low stock'):status_badge('Healthy') ?></td><td><a class="btn btn-sm btn-light" href="/?page=inventory&edit_id=<?= (int)$i['id'] ?>#inventory-form" title="Edit inventory"><i class="bi bi-pencil"></i></a></td></tr><?php endforeach; ?></tbody></table></div></div>
    <?php layout_end();
}

function render_wastage(Repository $repo): void { layout_start('Wastage control','wastage'); $w=$repo->all('wastage'); $ingredients=$repo->all('ingredients'); ?>
<section class="page-intro"><div><span class="eyebrow">LOSS PREVENTION</span><h2>Wastage control</h2><p>Record, classify, and reduce ingredient wastage across the kitchen.</p></div><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#wasteModal"><i class="bi bi-plus-lg me-2"></i>Record wastage</button></section><div class="content-grid"><div class="panel"><div class="panel-heading"><div><h3>Wastage trend</h3><p>Recorded quantity by recent service period.</p></div><span class="trend-down"><i class="bi bi-arrow-down-right"></i> 12% vs last period</span></div><div class="bar-chart"><div class="bar-group"><span class="bar" style="height:75%"></span><small>Mon</small></div><div class="bar-group"><span class="bar" style="height:52%"></span><small>Tue</small></div><div class="bar-group"><span class="bar" style="height:64%"></span><small>Wed</small></div><div class="bar-group"><span class="bar" style="height:38%"></span><small>Thu</small></div><div class="bar-group"><span class="bar active" style="height:28%"></span><small>Today</small></div></div></div><div class="panel"><div class="panel-heading"><div><h3>Top reasons</h3><p>Use this to target corrective action.</p></div></div><div class="reason-row"><span>Preparation trim</span><strong>48%</strong><div class="progress"><div class="progress-bar bg-purple" style="width:48%"></div></div></div><div class="reason-row"><span>Expiry / temperature</span><strong>31%</strong><div class="progress"><div class="progress-bar bg-orange" style="width:31%"></div></div></div><div class="reason-row"><span>Overproduction</span><strong>21%</strong><div class="progress"><div class="progress-bar bg-blue" style="width:21%"></div></div></div></div></div><div class="panel mt-4"><div class="panel-heading"><div><h3>Wastage register</h3><p>Auditable records for kitchen and stores review.</p></div></div><div class="table-responsive"><table class="table app-table"><thead><tr><th>Ingredient</th><th>Quantity</th><th>Reason</th><th>Recorded at</th><th>Recorded by</th></tr></thead><tbody><?php foreach($w as $r): ?><tr><td><strong><?= e($r['ingredient']) ?></strong></td><td><?= e($r['quantity']) ?> <?= e($r['unit']) ?></td><td><?= e($r['reason']) ?></td><td><?= e($r['recorded_at']) ?></td><td><?= e($r['recorded_by']) ?></td></tr><?php endforeach; ?></tbody></table></div></div><div class="modal fade" id="wasteModal" tabindex="-1"><div class="modal-dialog"><div class="modal-content"><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="record_wastage"><div class="modal-header"><h5 class="modal-title">Record wastage</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><label class="form-label">Ingredient</label><select name="ingredient_id" class="form-select mb-3" required><?php foreach($ingredients as $i): ?><option value="<?= $i['id'] ?>"><?= e($i['name'].' ('.$i['on_hand'].' '.$i['unit'].' available)') ?></option><?php endforeach; ?></select><label class="form-label">Quantity</label><input type="number" name="quantity" class="form-control mb-3" min="0" step="0.1" required><label class="form-label">Reason</label><select name="reason" class="form-select"><option>Preparation trim</option><option>Expired / temperature breach</option><option>Overproduction</option><option>Spillage / damage</option></select></div><div class="modal-footer"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Cancel</button><button class="btn btn-primary">Save record</button></div></form></div></div></div><?php layout_end(); }
